create or replace function public.record_location_departure(p_location_id uuid,p_lat double precision,p_lng double precision) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare uid uuid:=auth.uid(); loc record; distance_m double precision; radius_m double precision; departure_id uuid; begin if uid is null then raise exception 'AUTH_REQUIRED'; end if; if p_location_id is null or p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'LOCATION_REQUIRED'; end if; select id,latitude,longitude,coalesce(geofence_radius_m,150)::double precision radius_m into loc from public.locations where id=p_location_id and is_active=true; if not found then raise exception 'LOCATION_NOT_FOUND'; end if; if loc.latitude is null or loc.longitude is null then raise exception 'LOCATION_COORDINATES_UNAVAILABLE'; end if; radius_m:=greatest(25,least(coalesce(loc.radius_m,150),5000)); distance_m:=6371000.0*2*asin(sqrt(power(sin(radians(p_lat-loc.latitude)/2),2)+cos(radians(loc.latitude))*cos(radians(p_lat))*power(sin(radians(p_lng-loc.longitude)/2),2))); if distance_m<=radius_m then raise exception 'STILL_IN_GEOFENCE: distance=% radius=%',round(distance_m),round(radius_m); end if; if exists(select 1 from public.location_departures d where d.user_id=uid and d.location_id=p_location_id and d.left_at > now()-interval '10 minutes') then return jsonb_build_object('success',true,'already_recorded',true,'progression_reset',true); end if; insert into public.location_departures(user_id,location_id,left_at,latitude,longitude,distance_meters) values(uid,p_location_id,now(),p_lat,p_lng,distance_m) returning id into departure_id; return jsonb_build_object('success',true,'departure_id',departure_id,'progression_reset',true,'distance_meters',distance_m,'geofence_radius_meters',radius_m); end; $function$;
comment on function public.record_location_departure(uuid,double precision,double precision) is 'Records an authenticated users departure only after they are outside the canonical location geofence. Used to qualify a later return visit.';
revoke execute on function public.record_location_departure(uuid,double precision,double precision) from anon; grant execute on function public.record_location_departure(uuid,double precision,double precision) to authenticated;
